use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let m: int = 200001
    let mut sieve: Vec<bool> = []
    let mut i: int = 0
    while i < m {
        sieve.push(true)
        i += 1
    }
    let mut counts: Vec<int> = []
    let mut largest: Vec<int> = []
    let mut c: int = 0
    let mut last: int = -1
    let mut k: int = 0
    while k < m {
        if k >= 2 && sieve[k as usize] {
            c += 1
            last = k
            let mut j: int = k * k
            while j < m {
                sieve[j as usize] = false
                j += k
            }
        }
        counts.push(c)
        largest.push(last)
        k += 1
    }
    let mut first = true
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        if first {
            first = false
            continue
        }
        let n: int = t.parse::<int>().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${counts[n as usize]} ${largest[n as usize]}")
        }
    }
}

